import atexit, ctypes, json, os, sys
from pathlib import Path
_native_attempts = []
def _native_credential_tripwire(event, args):
    if event == 'ctypes.dlopen':
        name = os.path.basename(str(args[0]).replace('\\', '/')).lower()
        if name in {'advapi32', 'advapi32.dll'}:
            _native_attempts.append({'event': event, 'api': 'advapi32 loading'})
            raise AssertionError('Real Native CredentialVault DLL is forbidden during catalog generation')
    if event in {'ctypes.dlsym', 'ctypes.dlsym/handle'}:
        name = args[-1]
        if isinstance(name, bytes): name = name.decode('ascii', 'replace')
        if str(name).startswith('Cred'):
            _native_attempts.append({'event': event, 'api': str(name)})
            raise AssertionError('Real Cred* symbol resolution is forbidden during catalog generation')
sys.addaudithook(_native_credential_tripwire)
def _write_native_tripwire():
    Path('.profile/catalog-native-tripwire.json').write_text(json.dumps({'attempts': _native_attempts, 'real_native_credential_calls': 0}), encoding='utf-8')
atexit.register(_write_native_tripwire)

import json, os, runpy, sys
from pathlib import Path
root = Path.cwd().resolve()
omitted = root / 'docs' / 'delivery'
def reject_omitted_reads(event, args):
    if event == 'open' and isinstance(args[0], (str, bytes, os.PathLike)):
        path = Path(os.fsdecode(args[0])).resolve()
        if path == omitted or path.is_relative_to(omitted):
            raise RuntimeError('Compact catalog accessed excluded delivery evidence')
sys.addaudithook(reject_omitted_reads)
runpy.run_path(str(root / 'scripts/refresh_product_api_catalog.py'), run_name='__main__')
origins = {}
for name, module in list(sys.modules.items()):
    if name.split('.')[0] in {'app', 'local_interop_protocol', 'local_interop_desktop'}:
        for origin in [getattr(module, '__file__', None), *getattr(module, '__path__', [])]:
            if origin and not Path(origin).resolve().is_relative_to(root):
                raise RuntimeError('Project import escaped compact snapshot: ' + name)
        if getattr(module, '__file__', None):
            origins[name] = str(Path(module.__file__).resolve().relative_to(root))
(root / '.profile/catalog-import-origins.json').write_text(json.dumps(origins, sort_keys=True) + '\n')
